package org.brightstats.model;
import java.util.*;
import com.google.gson.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.stats.*;

/** Compile stable diagram identities into explicit statistical input; geometry is never data. */
public final class DiagramModels {
    private DiagramModels(){}
    public record Pls(List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,List<NonlinearPls.Extension> extensions,List<ComponentCopula.Specification> copulas,Map<String,Integer> identities,List<String> warnings){public Pls{blocks=List.copyOf(blocks);edges=List.copyOf(edges);extensions=List.copyOf(extensions);copulas=List.copyOf(copulas);identities=Collections.unmodifiableMap(new LinkedHashMap<>(identities));warnings=List.copyOf(warnings);}}
    public record Generalized(Gsca.Prepared prepared,List<NonlinearPls.Extension> extensions,List<ComponentCopula.Specification> copulas,Map<String,Integer> identities,List<String> warnings){public Generalized{extensions=List.copyOf(extensions);copulas=List.copyOf(copulas);identities=Collections.unmodifiableMap(new LinkedHashMap<>(identities));warnings=List.copyOf(warnings);}}
    public record Regression(int response,int[] predictors,boolean intercept,String responseNode,List<String> predictorNodes){public Regression{predictors=predictors.clone();predictorNodes=List.copyOf(predictorNodes);}@Override public int[] predictors(){return predictors.clone();}}
    record Term(String target,List<String> factors){Term{factors=List.copyOf(factors);}}
    public static Pls pls(Document document,List<String> columns){if(document.family()!=Family.PLS)throw new IllegalArgumentException("Choose a PLS diagram.");return components(document,columns,ElementType.LATENT_VARIABLE);}
    public static Generalized gsca(Document document,List<String> columns){if(document.family()!=Family.GSCA)throw new IllegalArgumentException("Choose a GSCA diagram.");var compiled=components(document,columns,ElementType.GSCA_LATENT_VARIABLE);var prepared=Gsca.fromBlocks(columns,compiled.blocks,compiled.edges);var model=prepared.model();boolean[][] weights=model.weights(),loadings=model.loadings();double[][] initial=model.initialWeights();int[] selected=prepared.columns();for(var link:document.links())if(link.type().measurement()){String component=compiled.identities.containsKey(link.source())?link.source():link.target();Node observed=document.node(component.equals(link.source())?link.target():link.source());int physical=column(observed.properties().get("column"),columns),row=-1;for(int i=0;i<selected.length;i++)if(selected[i]==physical)row=i;int target=compiled.identities.get(component);weights[row][target]=bool(link.properties(),"weight",weights[row][target]);loadings[row][target]=bool(link.properties(),"loading",loadings[row][target]);double requested=link.properties().has("initialWeight")?number(link.properties().get("initialWeight"),"GSCA initial weight"):initial[row][target];if(!weights[row][target]&&requested!=0&&link.properties().has("initialWeight"))throw new IllegalArgumentException("A disabled GSCA weight must have zero initial weight.");initial[row][target]=weights[row][target]?requested:0;}var exact=new Gsca.Prepared(new Gsca.Model(model.indicators(),model.components(),weights,loadings,model.paths(),initial),selected);return new Generalized(exact,compiled.extensions,compiled.copulas,compiled.identities,compiled.warnings);}
    private static Pls components(Document document,List<String> columns,ElementType latent){dataset(columns);if(document.nodes().stream().anyMatch(node->node.type()==ElementType.MODERATING_EFFECT))throw new IllegalArgumentException("Convert the legacy moderation marker to a typed path attachment before analysis.");List<Node> constructs=document.nodes().stream().filter(node->node.type()==latent).toList();if(constructs.isEmpty()||constructs.size()>64)throw new IllegalArgumentException("Define 1–64 measured component nodes.");Map<String,Integer> indices=new LinkedHashMap<>();Set<String> labels=new HashSet<>();List<PlsSem.Block> blocks=new ArrayList<>();for(var construct:constructs){if(construct.label().isBlank()||!labels.add(construct.label()))throw new IllegalArgumentException("Name component nodes uniquely.");indices.put(construct.id(),blocks.size());List<Integer> bound=bindings(document,construct,columns);var properties=construct.properties();var mode=PlsSem.Mode.valueOf(string(properties,"mode","A"));var measurement=PlsSem.MeasurementType.valueOf(string(properties,"measurementType",mode==PlsSem.Mode.A?"REFLECTIVE":"FORMATIVE"));double[] initial=null;if(properties.has("initialWeights")){var values=properties.getAsJsonArray("initialWeights");initial=new double[values.size()];double magnitude=0;for(int i=0;i<initial.length;i++){initial[i]=number(values.get(i),"initialWeights");magnitude+=Math.abs(initial[i]);}if(!(magnitude>0))throw new IllegalArgumentException("Initial component weights cannot all be zero.");}blocks.add(new PlsSem.Block(construct.label(),bound.stream().mapToInt(Integer::intValue).toArray(),mode,initial,measurement));}
        for(var link:document.links())if(link.type().measurement()){boolean source=indices.containsKey(link.source()),target=indices.containsKey(link.target());if(source==target||!document.node(source?link.target():link.source()).type().observed())throw new IllegalArgumentException("Each measurement connection must join one component and one observed indicator.");}
        for(var node:document.nodes())if((node.type()==ElementType.GAUSSIAN_COPULA||node.type()==ElementType.QUADRATIC_EFFECT)&&document.links().stream().noneMatch(link->link.source().equals(node.id())&&link.type().modifier()))throw new IllegalArgumentException("Attach effect marker "+node.label()+" to a model path before analysis.");
        List<PlsSem.Edge> paths=new ArrayList<>();Set<String> pathKeys=new HashSet<>();for(var link:document.links())if(link.type().structural()){if(!indices.containsKey(link.source())||!indices.containsKey(link.target()))throw new IllegalArgumentException("Component structural paths must join two component nodes.");if(link.properties().has("value")||link.properties().has("equality")||link.properties().has("lower")||link.properties().has("upper")||link.properties().has("free")&&!bool(link.properties(),"free",true))throw new IllegalArgumentException("PLS/GSCA paths are estimated freely. Use a text annotation for display labels or CB-SEM for fixed/equality constraints.");String key=link.source()+":"+link.target();if(!pathKeys.add(key))throw new IllegalArgumentException("Duplicate component structural path.");paths.add(new PlsSem.Edge(indices.get(link.source()),indices.get(link.target())));}
        List<NonlinearPls.Extension> extensions=new ArrayList<>();Set<String> terms=new HashSet<>();List<String>warnings=new ArrayList<>();for(var link:document.links())if(link.type().modifier()&&!gaussian(link.type())){Term term=term(document,link,new HashSet<>());Integer target=indices.get(term.target);if(target==null)throw new IllegalArgumentException("A polynomial target must be a component node.");int[] factors=term.factors.stream().mapToInt(id->{Integer index=indices.get(id);if(index==null)throw new IllegalArgumentException("Moderators must be measured component nodes.");return index;}).toArray();var extension=new NonlinearPls.Extension(target,factors);String key=target+":"+Arrays.toString(extension.factors());if(!terms.add(key))throw new IllegalArgumentException("Duplicate polynomial term on the same target.");extensions.add(extension);for(String factor:term.factors){String path=factor+":"+term.target;if(pathKeys.add(path)){paths.add(new PlsSem.Edge(indices.get(factor),target));warnings.add("Polynomial hierarchy adds main path "+document.node(factor).label()+" -> "+document.node(term.target).label()+".");}}}
        Map<Integer,List<Integer>> selected=new LinkedHashMap<>();Map<Integer,CopulaRegression.Method> methods=new HashMap<>();Map<Integer,CopulaRegression.PlottingPosition> positions=new HashMap<>();for(var link:document.links())if(gaussian(link.type())){Node marker=document.node(link.source());if(marker.type()!=ElementType.GAUSSIAN_COPULA)throw new IllegalArgumentException("A copula attachment must start at a Gaussian-copula marker.");Term attached=anchorTerm(document,document.node(link.target()),new HashSet<>());if(attached.factors.size()!=1)throw new IllegalArgumentException("This score-copula adapter requires a linear parent path; nonlinear/control-function combinations need an explicitly supported joint method.");Integer source=indices.get(attached.factors.getFirst()),target=indices.get(attached.target);if(source==null||target==null)throw new IllegalArgumentException("Copula attachments need measured component endpoints.");var method=CopulaRegression.Method.valueOf(string(marker.properties(),"method","ORIGINAL_GAUSSIAN"));var position=CopulaRegression.PlottingPosition.valueOf(string(marker.properties(),"plottingPosition","WEIBULL"));if(methods.containsKey(target)&&(methods.get(target)!=method||positions.get(target)!=position))throw new IllegalArgumentException("Use one control-function method and plotting position per target equation.");methods.put(target,method);positions.put(target,position);var values=selected.computeIfAbsent(target,unused->new ArrayList<>());if(values.contains(source))throw new IllegalArgumentException("Duplicate copula control on one parent path.");values.add(source);}
        List<ComponentCopula.Specification> copulas=new ArrayList<>();for(var entry:selected.entrySet()){int target=entry.getKey();long parents=paths.stream().filter(path->path.target()==target).count();if(methods.get(target)==CopulaRegression.Method.TWO_STAGE_GAUSSIAN&&parents==entry.getValue().size())throw new IllegalArgumentException("2sCOPE requires an unselected exogenous parent in each corrected equation.");copulas.add(new ComponentCopula.Specification(target,entry.getValue().stream().mapToInt(Integer::intValue).toArray(),methods.get(target),positions.get(target)));}
        if(document.family()==Family.PLS)dag(blocks.size(),paths);return new Pls(blocks,paths,extensions,copulas,indices,warnings);
    }
    private static List<Integer> bindings(Document document,Node construct,List<String> columns){List<Integer> result=new ArrayList<>();var properties=construct.properties();if(properties.has("columns"))for(var value:properties.getAsJsonArray("columns"))result.add(column(value,columns));for(var link:document.links())if(link.type().measurement()&&(link.source().equals(construct.id())||link.target().equals(construct.id()))){Node observed=document.node(link.source().equals(construct.id())?link.target():link.source());if(!observed.type().observed())throw new IllegalArgumentException("A component measurement link must join a component and an observed indicator.");result.add(column(observed.properties().get("column"),columns));}if(result.isEmpty())throw new IllegalArgumentException("Bind indicators to "+construct.label()+".");if(new HashSet<>(result).size()!=result.size())throw new IllegalArgumentException("Duplicate indicator binding within "+construct.label()+".");return List.copyOf(result);}
    static Term term(Document document,Link link,Set<String> visited){if(!visited.add(link.id())||visited.size()>8)throw new IllegalArgumentException("Invalid interaction attachment chain.");if(link.type().structural())return new Term(link.target(),List.of(link.source()));if(!link.type().modifier()||gaussian(link.type()))throw new IllegalArgumentException("Choose a structural, moderation or quadratic path attachment.");Term base=anchorTerm(document,document.node(link.target()),visited);List<String> factors=new ArrayList<>(base.factors);Node source=document.node(link.source());if(link.type().name().contains("MODERATION")){if(!source.type().latent()&&!(document.family()==Family.CBSEM&&source.type().observed()))throw new IllegalArgumentException("A moderator must be a measured component or a CB-SEM observed variable.");factors.add(source.id());}else{if(source.type()!=ElementType.QUADRATIC_EFFECT&&source.type()!=ElementType.PROCESS_MODEL_QUADRATIC_EFFECT||factors.size()!=1)throw new IllegalArgumentException("A quadratic marker must attach directly to a linear path.");factors.add(factors.getFirst());}if(factors.size()>3)throw new IllegalArgumentException("Polynomial attachments currently support total degree at most three.");return new Term(base.target,factors);}
    static Term anchorTerm(Document document,Node anchor,Set<String> visited){if(anchor.type()!=ElementType.DONGLE||!anchor.properties().has("edge"))throw new IllegalArgumentException("Attach this effect to a path anchor.");return term(document,document.link(string(anchor.properties(),"edge",null)),visited);}
    private static boolean gaussian(ElementType type){return type.name().contains("BETWEEN_GAUSSIAN_COPULA");}
    public static Regression regression(Document document,List<String> columns){if(document.family()!=Family.REGRESSION)throw new IllegalArgumentException("Choose a regression diagram.");dataset(columns);List<Node> outcomes=document.nodes().stream().filter(node->node.type()==ElementType.REGRESSION_DEPENDENT_VARIABLE).toList();if(outcomes.size()!=1)throw new IllegalArgumentException("A regression diagram requires exactly one dependent variable.");Node outcome=outcomes.getFirst();int response=column(outcome.properties().get("column"),columns);List<Integer> predictors=new ArrayList<>();List<String> nodes=new ArrayList<>();boolean intercept=false;for(var link:document.links())if(link.type()==ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INDEPENDENT_VARIABLE||link.type()==ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INTERCEPT){Node peer;if(link.source().equals(outcome.id()))peer=document.node(link.target());else if(link.target().equals(outcome.id()))peer=document.node(link.source());else throw new IllegalArgumentException("Connect regression predictors and intercept to the dependent variable.");if(link.type()==ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INTERCEPT){if(peer.type()!=ElementType.REGRESSION_INTERCEPT||intercept)throw new IllegalArgumentException("Use one connected intercept node.");intercept=true;}else{if(peer.type()!=ElementType.REGRESSION_INDEPENDENT_VARIABLE)throw new IllegalArgumentException("Choose an independent-variable node for this regression connection.");int predictor=column(peer.properties().get("column"),columns);if(predictor==response||predictors.contains(predictor))throw new IllegalArgumentException("Regression columns must be distinct from the outcome and one another.");predictors.add(predictor);nodes.add(peer.id());}}if(predictors.isEmpty()&&!intercept)throw new IllegalArgumentException("Connect a predictor or an intercept.");return new Regression(response,predictors.stream().mapToInt(Integer::intValue).toArray(),intercept,outcome.id(),nodes);}
    public static Optional<CopulaRegression.Model> regressionCopula(Document document,List<String> columns){var regression=regression(document,columns);List<Node> markers=document.nodes().stream().filter(node->node.type()==ElementType.GAUSSIAN_COPULA).toList();for(var link:document.links())if(link.type()==ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION&&document.node(link.source()).type()!=ElementType.GAUSSIAN_COPULA)throw new IllegalArgumentException("Gaussian-copula attachments require a copula source node.");if(markers.isEmpty())return Optional.empty();if(!regression.intercept())throw new IllegalArgumentException("This copula control-function contract requires a connected intercept.");Set<Integer> endogenous=new TreeSet<>();CopulaRegression.Method method=null;CopulaRegression.PlottingPosition position=null;for(var marker:markers){var attached=document.links().stream().filter(link->link.source().equals(marker.id())&&link.type()==ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION).toList();if(attached.isEmpty())throw new IllegalArgumentException("Attach every Gaussian-copula marker to a predictor path.");var requested=CopulaRegression.Method.valueOf(string(marker.properties(),"method","ORIGINAL_GAUSSIAN"));var plotting=CopulaRegression.PlottingPosition.valueOf(string(marker.properties(),"plottingPosition","WEIBULL"));if(method!=null&&(method!=requested||position!=plotting))throw new IllegalArgumentException("One regression equation must use a consistent copula method and plotting position.");method=requested;position=plotting;for(var link:attached){var anchor=document.node(link.target());if(anchor.type()!=ElementType.DONGLE)throw new IllegalArgumentException("Attach copulas through a path anchor.");var base=document.link(string(anchor.properties(),"edge",null));if(base.type()!=ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INDEPENDENT_VARIABLE)throw new IllegalArgumentException("A regression copula must target a predictor-to-outcome path.");String predictor=base.source().equals(regression.responseNode())?base.target():base.target().equals(regression.responseNode())?base.source():"";int index=regression.predictorNodes().indexOf(predictor);if(index<0)throw new IllegalArgumentException("Copula path is outside the selected regression equation.");endogenous.add(index);}}return Optional.of(new CopulaRegression.Model(Arrays.stream(regression.predictors()).mapToObj(columns::get).toList(),endogenous.stream().mapToInt(Integer::intValue).toArray(),method,position));}
    public static String string(JsonObject properties,String name,String fallback){var value=properties.get(name);if(value==null)return fallback;if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Diagram property "+name+" must be text.");return value.getAsString();}
    public static boolean bool(JsonObject properties,String name,boolean fallback){var value=properties.get(name);if(value==null)return fallback;if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isBoolean())throw new IllegalArgumentException("Diagram property "+name+" must be boolean.");return value.getAsBoolean();}
    public static double number(JsonElement value,String name){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isNumber()||!Double.isFinite(value.getAsDouble()))throw new IllegalArgumentException("Diagram property "+name+" must be finite numeric data.");return value.getAsDouble();}
    private static int column(JsonElement value,List<String> names){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Bind each observed indicator to a dataset column name.");int index=names.indexOf(value.getAsString());if(index<0)throw new IllegalArgumentException("Bound data column is missing: "+value.getAsString());return index;}
    private static void dataset(List<String> names){if(names.isEmpty()||new HashSet<>(names).size()!=names.size())throw new IllegalArgumentException("Use a dataset with unique column names.");}
    private static void dag(int size,List<PlsSem.Edge> edges){int[] degree=new int[size];for(var edge:edges)degree[edge.target()]++;ArrayDeque<Integer> ready=new ArrayDeque<>();for(int i=0;i<size;i++)if(degree[i]==0)ready.add(i);int count=0;while(!ready.isEmpty()){int node=ready.removeFirst();count++;for(var edge:edges)if(edge.source()==node&&--degree[edge.target()]==0)ready.add(edge.target());}if(count!=size)throw new IllegalArgumentException("Structural paths, including required polynomial main effects, must be acyclic for PLS.");}
}
